#' Clinical ROC Analysis
#'
#' 
#' @param data .
#' @param reference .
#' @param positive .
#' @param marker1 .
#' @param marker2 .
#' @param marker3 .
#' @param direction1 .
#' @param direction2 .
#' @param direction3 .
#' @param confLevel .
#' @param showComparisons .
#' @param showThresholds .
#' @param showCases .
#' @param showROC .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$auc} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$comparisons} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$thresholds} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rocPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pyenhancedroc <- function(
    data,
    reference = NULL,
    positive,
    marker1 = NULL,
    marker2 = NULL,
    marker3 = NULL,
    direction1 = "higher",
    direction2 = "higher",
    direction3 = "higher",
    confLevel = 0.95,
    showComparisons = TRUE,
    showThresholds = FALSE,
    showCases = FALSE,
    showROC = TRUE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pyenhancedroc requires jmvcore to be installed (restart may be required)")

    if ( ! missing(reference)) reference <- jmvcore::resolveQuo(jmvcore::enquo(reference))
    if ( ! missing(marker1)) marker1 <- jmvcore::resolveQuo(jmvcore::enquo(marker1))
    if ( ! missing(marker2)) marker2 <- jmvcore::resolveQuo(jmvcore::enquo(marker2))
    if ( ! missing(marker3)) marker3 <- jmvcore::resolveQuo(jmvcore::enquo(marker3))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(reference), reference, NULL),
            `if`( ! missing(marker1), marker1, NULL),
            `if`( ! missing(marker2), marker2, NULL),
            `if`( ! missing(marker3), marker3, NULL))

    for (v in reference) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pyenhancedrocOptions$new(
        reference = reference,
        positive = positive,
        marker1 = marker1,
        marker2 = marker2,
        marker3 = marker3,
        direction1 = direction1,
        direction2 = direction2,
        direction3 = direction3,
        confLevel = confLevel,
        showComparisons = showComparisons,
        showThresholds = showThresholds,
        showCases = showCases,
        showROC = showROC,
        showConsole = showConsole)

    analysis <- pyenhancedrocClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

